CREATE TABLE users (id INTEGER PRIMARY KEY, full_name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE feedback (id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, subject VARCHAR(100) NOT NULL, work_type VARCHAR(30) NOT NULL, deadline DATE NOT NULL, difficulty VARCHAR(10) NOT NULL, stress VARCHAR(10) NOT NULL, feedback_text TEXT NOT NULL CHECK (length(feedback_text) BETWEEN 1 AND 1000), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
